package com.mcpocket.poc;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** Official PickPico white logo + wordmark used by the product UI. */
final class PickPicoBrand {
    private static final String WHITE_LOGO_PNG =
            "";
    private static final String WHITE_WORDMARK_PNG =
            "";

    private PickPicoBrand() {
    }

    static Bitmap whiteWordmark() {
        byte[] data = Base64.decode(WHITE_WORDMARK_PNG, Base64.DEFAULT);
        return BitmapFactory.decodeByteArray(data, 0, data.length);
    }

    static Bitmap whiteLogo() {
        byte[] data = Base64.decode(WHITE_LOGO_PNG, Base64.DEFAULT);
        return BitmapFactory.decodeByteArray(data, 0, data.length);
    }
}
